"""LLM Decision Agent: the only step in the pipeline that calls an LLM.

Takes the Revenue Optimizer's shortlists plus the raw signals (comp median,
pace, gap flags, guardrails) and asks Claude to pick a final price per
listing per date and explain why in plain language — including how it's
weighing the twin-listing tradeoff. Everything upstream is deterministic;
this step exists because *synthesizing competing signals into one number
with a defensible rationale* is the one part that benefits from reasoning.
"""

import json
import os

import anthropic

MODEL = os.environ.get("ANTHROPIC_MODEL", "claude-sonnet-5")

DECISION_TOOL = {
    "name": "submit_pricing_decisions",
    "description": "Submit final nightly price recommendations with rationale.",
    "input_schema": {
        "type": "object",
        "properties": {
            "decisions": {
                "type": "array",
                "items": {
                    "type": "object",
                    "properties": {
                        "listing_id": {"type": "string"},
                        "date": {"type": "string"},
                        "recommended_price": {"type": "number"},
                        "rationale": {"type": "string"},
                    },
                    "required": ["listing_id", "date", "recommended_price", "rationale"],
                },
            }
        },
        "required": ["decisions"],
    },
}


def _build_prompt(signals_by_listing: dict, guardrails: dict) -> str:
    return f"""You are pricing two nearly-identical 4bd/2ba Airbnb listings that are
one block apart and effectively compete for the same guests.

Guardrails (must not be violated): {json.dumps(guardrails)}

For each listing/date below, you're given: the Revenue Optimizer's top
candidate prices with their expected-revenue scores, the comp market
median, the booking pace ratio (below 1.0 = behind historical pace), and
whether it's an orphan gap night.

Pick ONE final price per listing per date. Favor the optimizer's top
candidate unless the signals justify a different pick — explain why in
one or two sentences, including any twin-listing tradeoff (e.g. steering
one listing cheaper to fill it while the other captures a higher rate).

Signals:
{json.dumps(signals_by_listing, indent=2)}

Call submit_pricing_decisions with your final decisions.
"""


def _fallback_decisions(signals_by_listing: dict) -> list[dict]:
    """Used when no ANTHROPIC_API_KEY is set: skips the LLM synthesis step and
    just takes the Revenue Optimizer's top-scored candidate per listing/date.
    """
    decisions = []
    for listing_id, signals in signals_by_listing.items():
        for d, shortlist in signals.get("shortlists", {}).items():
            if not shortlist:
                continue
            decisions.append(
                {
                    "listing_id": listing_id,
                    "date": d,
                    "recommended_price": shortlist[0]["price"],
                    "rationale": "LLM decision step skipped (no ANTHROPIC_API_KEY) — used Revenue Optimizer's top candidate.",
                }
            )
    return decisions


def run(signals_by_listing: dict, guardrails: dict) -> list[dict]:
    if not os.environ.get("ANTHROPIC_API_KEY"):
        return _fallback_decisions(signals_by_listing)

    client = anthropic.Anthropic()
    prompt = _build_prompt(signals_by_listing, guardrails)

    response = client.messages.create(
        model=MODEL,
        max_tokens=4096,
        tools=[DECISION_TOOL],
        tool_choice={"type": "tool", "name": "submit_pricing_decisions"},
        messages=[{"role": "user", "content": prompt}],
    )

    for block in response.content:
        if block.type == "tool_use" and block.name == "submit_pricing_decisions":
            return block.input["decisions"]
    raise RuntimeError("Decision agent did not return a tool call — check the model response.")

"""Revenue Optimizer: deterministic candidate-price scoring.

For each night and each listing, builds a grid of candidate prices, scores
each by estimated booking probability x price (expected revenue), and keeps
a shortlist. Then applies the twin-listing coordination rule across the two
listings for the same date, since they compete for the same guest search.

This is a simple, transparent heuristic model meant to be tuned once real
outcomes (bookings vs. price) start accumulating — not a trained model.
"""

import math
import statistics
from datetime import date, timedelta


def _sigmoid(x: float) -> float:
    return 1 / (1 + math.exp(-x))


def _comp_median_by_date(comp_snapshots: list[dict]) -> dict[str, float]:
    by_date: dict[str, list[float]] = {}
    for row in comp_snapshots:
        if row.get("price") is None or not row.get("available"):
            continue
        by_date.setdefault(row["date"], []).append(row["price"])
    return {d: statistics.median(prices) for d, prices in by_date.items() if prices}


def _candidate_grid(current_price: float, guardrails: dict) -> list[float]:
    max_change = guardrails["max_daily_change_pct"] / 100
    steps = [-max_change, -max_change * 0.66, -max_change * 0.33, 0, max_change * 0.33, max_change * 0.66, max_change]
    candidates = [current_price * (1 + step) for step in steps]
    return [
        max(guardrails["price_floor"], min(guardrails["price_ceiling"], round(c)))
        for c in candidates
    ]


def _booking_probability(
    candidate_price: float, comp_median: float, pace_ratio: float, is_gap_night: bool, at_risk_weight: float = 0.0
) -> float:
    """Heuristic, not a fitted model: higher than comp median -> lower probability;
    behind pace, a gap night, or at risk of becoming one -> more sensitive to
    price (more urgency to fill).
    """
    price_delta_pct = (candidate_price - comp_median) / comp_median if comp_median else 0
    urgency = 1.0
    if pace_ratio < 0.9:
        urgency += 0.5
    if is_gap_night:
        urgency += 0.5
    else:
        urgency += 0.5 * at_risk_weight
    return _sigmoid(-3 * urgency * price_delta_pct)


def score_listing(
    listing_id: str,
    own_calendar_rows: list[dict],
    comp_snapshots: list[dict],
    pace_ratio: float,
    gap_nights: set[str],
    guardrails: dict,
    at_risk_nights: dict[str, float] | None = None,
) -> dict[str, list[dict]]:
    """Returns {date: [ {price, expected_prob, expected_revenue}, ... top 3 ] }."""
    comp_median = _comp_median_by_date(comp_snapshots)
    window_end = date.today() + timedelta(days=guardrails["pricing_window_days"])
    at_risk_nights = at_risk_nights or {}

    shortlists = {}
    for row in own_calendar_rows:
        d = row.get("date")
        if not d or row.get("booked") or date.fromisoformat(d) > window_end:
            continue
        current_price = row.get("price") or guardrails["price_floor"]
        median = comp_median.get(d, current_price)
        is_gap = d in gap_nights
        risk_weight = at_risk_nights.get(d, 0.0)

        scored = []
        for candidate in _candidate_grid(current_price, guardrails):
            prob = _booking_probability(candidate, median, pace_ratio, is_gap, risk_weight)
            scored.append(
                {
                    "price": candidate,
                    "expected_prob": round(prob, 3),
                    "expected_revenue": round(candidate * prob, 2),
                }
            )
        scored.sort(key=lambda s: s["expected_revenue"], reverse=True)
        shortlists[d] = scored[:3]

    return shortlists


def coordinate_twin_listings(
    shortlists_by_listing: dict[str, dict[str, list[dict]]],
    pace_by_listing: dict[str, float],
    min_gap: float,
    guardrails: dict | None = None,
) -> dict[str, dict[str, list[dict]]]:
    """Enforces a minimum price gap between two listings on the same date, so
    they never tie and effectively split the same guest search 50/50.
    Whichever listing is further behind pace gets steered to be the cheaper
    one for that date, since it needs the booking more.
    """
    listing_ids = list(shortlists_by_listing.keys())
    if len(listing_ids) != 2:
        return shortlists_by_listing  # coordination only defined for the 2-listing case

    guardrails = guardrails or {}
    price_ceiling = guardrails.get("price_ceiling", math.inf)
    price_floor = guardrails.get("price_floor", -math.inf)

    a_id, b_id = listing_ids
    a_shortlists, b_shortlists = shortlists_by_listing[a_id], shortlists_by_listing[b_id]
    a_needier = pace_by_listing.get(a_id, 1.0) <= pace_by_listing.get(b_id, 1.0)

    shared_dates = set(a_shortlists) & set(b_shortlists)
    for d in shared_dates:
        a_best, b_best = a_shortlists[d][0], b_shortlists[d][0]
        if abs(a_best["price"] - b_best["price"]) >= min_gap:
            continue

        cheaper, pricier = (a_best, b_best) if a_needier else (b_best, a_best)
        # Pushing pricier up by min_gap can break the ceiling; if so, pin
        # pricier to the ceiling and pull cheaper down instead, so the gap
        # is preserved without violating either guardrail.
        if cheaper["price"] + min_gap > price_ceiling:
            pricier["price"] = price_ceiling
            cheaper["price"] = max(price_floor, price_ceiling - min_gap)
        else:
            pricier["price"] = cheaper["price"] + min_gap

    return {a_id: a_shortlists, b_id: b_shortlists}

